/// <summary>
/// Event handler class
/// </summary>
internal final class METGUPPriceDiscPricingRulePreviewEventHandler
{

}

Method.Source:
/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(GUPPriceDiscPricingRulePreview, Search), FormControlEventType::Clicked)]
public static void Search_OnClicked(FormControl sender, FormControlEventArgs e)
{
    InventTable                 inventTable;
    EcoResProductTranslation    ecoResProductTranslation;
    FormRun                     formRun     = sender.formRun() as FormRun;
    FormDataSource              formDS      = formRun.dataSource(formDataSourceStr(GUPPriceDiscPricingRulePreview, InventTable));
    FormStringControl           nameCtrl    = formRun.design().controlName(formControlStr(GUPPriceDiscPricingRulePreview, NameFilterString));

    select firstonly ecoResProductTranslation
        where ecoResProductTranslation.Name == nameCtrl.text();

    select firstonly inventTable
        where inventTable.Product == ecoResProductTranslation.Product;

    if (inventTable && nameCtrl.text())
    {
        formDS.filter(fieldnum(InventTable,ItemId), inventTable.ItemId);
    }
    else if (nameCtrl.text())
    {
        Query                   query = formDS.query();
        QueryBuildDataSource    inventQbds;
        QueryBuildDataSource    qbds;

        query.clearQueryFilters();

        inventQbds = query.dataSourceTable(tableNum(InventTable));

        inventQbds.clearRanges();

        qbds = inventQbds.addDataSource(tableNum(EcoResProductTranslation));

        qbds.clearRanges();

        qbds.joinMode(JoinMode::InnerJoin);
        qbds.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductTranslation, Product));

        qbds.addRange(fieldNum(EcoResProductTranslation, Name)).value(strFmt('*%1*', nameCtrl.text()));

        formDS.executeQuery();
    }
    else
    {
        formDS.filter(fieldnum(InventTable,ItemId), '');
    }

    formDS.refresh();
    formDS.reread();
    formDS.research(true);
}
